/// Endpoints of `client.balance().withdrawals()`.
#[derive(Debug, Clone, Copy)]
pub struct BalanceWithdrawals<'a> {
    client: &'a Client,
}

impl BalanceWithdrawals<'_> {
    /// Withdraw crypto to an external address
    ///
    /// Executes a calculation made with `balance.withdrawals.calculate_crypto` (address, amount
    /// and network are taken from it). Needs an operation MFA token for `WITHDRAWAL`; without
    /// it the service answers "Operation denied, requires mfa checking". Errors:
    /// `INVALID_CALCULATION` (calculation expired, calculate again),
    /// `ACTIVE_WITHDRAWAL_REQUEST_FOUND`, `ACTIVE_BALANCE_OPERATION_FOUND`, `INVALID_ADDRESS`,
    /// `DESTINATION_ADDRESS_IS_INTERNAL`, `INVALID_AMOUNT` (commission exceeds the amount),
    /// `INVALID_MIN_LIMIT`, `INVALID_MAX_LIMIT`, `INVALID_MFA_STATUS`, `INVALID_MFA_CODE`,
    /// `AML_FRAUD_VALIDATION_ERROR`, `BALANCE_OPERATION_PROCESSING_ERROR`.
    ///
    /// `POST /api/v2/exchange/client/balance/crypto/withdrawal`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// Needs an operation MFA token for `WITHDRAWAL`, which the client obtains with
    /// [`Client::confirm_operation`](crate::Client::confirm_operation) when a one-time code
    /// provider is configured.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn create_crypto(
        &self,
        params: BalanceWithdrawalsCreateCryptoParams,
    ) -> Result<Value> {
        self.client
            .request(
                Service::Api,
                Method::POST,
                "/api/v2/exchange/client/balance/crypto/withdrawal",
            )
            .mfa_operation("WITHDRAWAL")
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Withdraw fiat to a card or bank account
    ///
    /// Needs an operation MFA token for `WITHDRAWAL`. `paymentToken` is the id of a bound card
    /// / payment method (`payments.methods.list`), or the QR ticket id for `MTS_QR` payments.
    /// `bankIdentifier` selects the recipient bank for SBP-style providers. Same errors as the
    /// crypto withdrawal.
    ///
    /// `POST /api/v2/exchange/client/balance/fiat/withdrawal`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// Needs an operation MFA token for `WITHDRAWAL`, which the client obtains with
    /// [`Client::confirm_operation`](crate::Client::confirm_operation) when a one-time code
    /// provider is configured.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn create_fiat(&self, params: BalanceWithdrawalsCreateFiatParams) -> Result<Value> {
        self.client
            .request(
                Service::Api,
                Method::POST,
                "/api/v2/exchange/client/balance/fiat/withdrawal",
            )
            .mfa_operation("WITHDRAWAL")
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Calculate a crypto withdrawal
    ///
    /// Returns the commission, the received amount and a calculation `id` valid until
    /// `expirationDate`.
    ///
    /// `POST /api/v2/exchange/client/balance/crypto/withdrawal/calculate`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn calculate_crypto(
        &self,
        params: BalanceWithdrawalsCalculateCryptoParams,
    ) -> Result<BalanceCalculation> {
        self.client
            .request(
                Service::Api,
                Method::POST,
                "/api/v2/exchange/client/balance/crypto/withdrawal/calculate",
            )
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Calculate a fiat withdrawal
    ///
    /// `POST /api/v2/exchange/client/balance/fiat/withdrawal/calculate`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn calculate_fiat(
        &self,
        params: BalanceWithdrawalsCalculateFiatParams,
    ) -> Result<BalanceCalculation> {
        self.client
            .request(
                Service::Api,
                Method::POST,
                "/api/v2/exchange/client/balance/fiat/withdrawal/calculate",
            )
            .json(params)
            .send()
            .await?
            .json()
            .await
    }
}

