/// Endpoints of `client.kyc().liveness()`.
#[derive(Debug, Clone, Copy)]
pub struct KycLiveness<'a> {
    client: &'a Client,
}

impl KycLiveness<'_> {
    /// Start a liveness check
    ///
    /// Requested after an API call fails with 400 `LIVENESS_VERIFICATION_REQUIRED`; once the
    /// check passes the web app replays the failed call. With status `PROCESSING` the client
    /// opens `iframeUrl` (the PIN provider, origin `<https://verification.svort.io`>) on this
    /// device or shows it as a QR code for another device, then polls `kyc.liveness.status`
    /// every 2 seconds.
    ///
    /// `POST /api/v2/kyc/liveness/start`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn start(&self, params: KycLivenessStartParams) -> Result<KycLivenessSession> {
        self.client
            .request(Service::Api, Method::POST, "/api/v2/kyc/liveness/start")
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Restart a liveness check
    ///
    /// Used when the status is `RETRY_NEEDED` or the QR code expired. Statuses
    /// `MAX_ATTEMPTS_EXCEEDED` and `LIVENESS_NOT_FOUND` mean no further attempt is possible.
    ///
    /// `POST /api/v2/kyc/liveness/retry`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn retry(&self) -> Result<KycLivenessSession> {
        self.client
            .request(Service::Api, Method::POST, "/api/v2/kyc/liveness/retry")
            .json(Map::new())
            .send()
            .await?
            .json()
            .await
    }

    /// Get the liveness check status
    ///
    /// Returns the status as a bare string. `PASSED` is success, `PROCESSING` means keep
    /// polling, `RETRY_NEEDED` calls for `kyc.liveness.retry`; `EXPIRED`, `FAILED` and `ERROR`
    /// end the check.
    ///
    /// `GET /api/v2/kyc/liveness/status`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn status(&self) -> Result<KycLivenessStatus> {
        self.client
            .request(Service::Api, Method::GET, "/api/v2/kyc/liveness/status")
            .send()
            .await?
            .json()
            .await
    }
}

