/// Endpoints of `client.notifications()`.
#[derive(Debug, Clone, Copy)]
pub struct Notifications<'a> {
    client: &'a Client,
}

impl Notifications<'_> {
    /// Search notification events
    ///
    /// Spring Data page of the user's notification events. The web app asks for unread events
    /// only (`{"viewed": false}`), 5 per page, sorted by `creationDate,DESC`, and loads further
    /// pages on scroll while `page \< totalPages`.
    ///
    /// `POST /api/v1/notifications/events/search`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// Returns a lazy stream over the items of every page; it yields errors as items.
    pub fn search(&self, params: NotificationsSearchParams) -> Paginator<NotificationEvent> {
        self.client
            .request(
                Service::Notification,
                Method::POST,
                "/api/v1/notifications/events/search",
            )
            .query("page", params.page)
            .query("size", params.size)
            .query("sort", &params.sort)
            .json(params)
            .paginate(PageParam::Query("page"))
    }

    /// Mark notification events as viewed
    ///
    /// The web app sends one id at a time when the user dismisses an event and ignores the
    /// response.
    ///
    /// `PUT /api/v1/notifications/events/viewed`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails.
    pub async fn mark_viewed(&self, params: NotificationsMarkViewedParams) -> Result<()> {
        self.client
            .request(
                Service::Notification,
                Method::PUT,
                "/api/v1/notifications/events/viewed",
            )
            .json(params)
            .send()
            .await?;
        Ok(())
    }

    /// Stream real-time account updates
    ///
    /// Server-Sent Events stream of account updates (order progress, balance operations, KYC
    /// applicant and client status). The web app opens it with `fetch` (not `EventSource`) so
    /// it can send `Authorization: Bearer \<access token\>` and `Accept-Language`; it sends
    /// `Accept: text/event-stream` and optionally `Cache-Control: no-cache, no-store,
    /// must-revalidate` / `Pragma: no-cache`.
    ///
    /// Every message carries a JSON `data` field (`NotificationStreamMessage`); the SSE `event`
    /// name is not used for routing, messages are dispatched on `data.type`:
    ///
    /// - `ORDER_UPDATE`: `payload` is `NotificationOrderUpdate` (exchange order progress).
    /// - `BALANCE_OPERATION_UPDATE`: `payload` is `NotificationBalanceOperationUpdate`
    ///   (deposits and withdrawals).
    /// - `APPLICANT_STATUS_UPDATE`: `payload` is a string, e.g. `APPLICANT_OPENED` (KYC
    ///   applicant opened on the verification page).
    /// - `CLIENT_STATUS_UPDATE`: client status change; `payload` shape not used by the web app.
    ///
    /// Messages without `data` (keep-alive comments) are ignored. The `id` of the last message
    /// is sent back as `Last-Event-ID` on reconnect. The web app reconnects with backoff 1 s x
    /// 4^(n-1), capped at 30 s; 401/403 are fatal (re-authenticate before reconnecting). It
    /// also reconnects when the UI language changes, since the server localises messages by
    /// `Accept-Language`.
    ///
    /// `GET /api/v1/sse/connect`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// Returns a stream of events that reconnects automatically; it yields errors as items.
    pub fn stream(&self) -> EventStream<NotificationStreamMessage> {
        self.client
            .request(Service::Notification, Method::GET, "/api/v1/sse/connect")
            .events()
    }
}

