/// Endpoints of `client.providers().mts().qr()`.
#[derive(Debug, Clone, Copy)]
pub struct ProvidersMtsQr<'a> {
    client: &'a Client,
}

impl ProvidersMtsQr<'_> {
    /// Decode an SBP QR code
    ///
    /// First step of paying a Russian merchant's SBP (Faster Payments System) QR code from the
    /// Whitebird balance. The request carries the scanned QR content; the response is a payment
    /// ticket (`qrTicketId`) used by the next steps:
    ///
    /// 1. Check `error.code`: anything but `0` is a failure described by `error.message` (in
    ///    Russian; e.g. code `102` means the QR code was not found). The web app also refuses
    ///    tickets with more than one entry in `payments`.
    /// 2. For a static QR code (`payments\[0\].qrType == "static"`) the payer chooses the
    ///    amount and gets the amount to pay from `commission`; otherwise the amount is
    ///    `payments\[0\].settlementAmount`.
    /// 3. Pay through the exchange API: from a RUB balance with a fiat withdrawal
    ///    (`fiatProviderType: MTS_QR`, `paymentToken: qrTicketId`, `commissionType: ADD`), or
    ///    by selling crypto with a quote whose output is `{type: FIAT_PROVIDER, provider:
    ///    MTS_QR, token: qrTicketId}`.
    ///
    /// `POST /api/v1/qr/info`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn info(&self, params: ProvidersMtsQrInfoParams) -> Result<MtsQrInfo> {
        self.client
            .request(Service::Mts, Method::POST, "/api/v1/qr/info")
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Calculate the amount to pay for a static SBP QR code
    ///
    /// Used for static QR codes, where the payer enters the amount. The returned `amount` is
    /// what the web app then pays (see `info` for the whole flow).
    ///
    /// `POST /api/v1/qr/payment/commission`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn commission(
        &self,
        params: ProvidersMtsQrCommissionParams,
    ) -> Result<MtsQrCommission> {
        self.client
            .request(Service::Mts, Method::POST, "/api/v1/qr/payment/commission")
            .json(params)
            .send()
            .await?
            .json()
            .await
    }
}

