    /// Apply for a StatusBank crypto card
    ///
    /// Registers the client with StatusBank and starts issuing a card of the chosen type. The
    /// web app first calls the KYC service (`POST /api/v1/kyc/client/validate`); unless it
    /// reports `clientStatus: VERIFIED`, the user reviews the personal data that will be sent
    /// to the bank and confirms it (`POST /api/v1/kyc/client/confirm`). For the first card the
    /// web app requests `MASTERCARD`/`BYN`; further cards use a type from `card_systems`.
    ///
    /// On success the response carries `iFrame`: the bank's application page, which the user
    /// completes in a browser. `errorMessage` signals a failure, explained by `status`;
    /// `DATA_REQUIRED` with the message `gender is required` means the profile needs a gender.
    ///
    /// `POST /api/v1/statusbank/client/register`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn register_card(
        &self,
        params: ProvidersStatusbankRegisterCardParams,
    ) -> Result<StatusbankRegistration> {
        self.client
            .request(
                Service::Statusbank,
                Method::POST,
                "/api/v1/statusbank/client/register",
            )
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Get the StatusBank page with a card's balance and details
    ///
    /// The balance and card details are not returned as data; open `iFrame` in a browser to
    /// show them. `errorMessage` is set on failure.
    ///
