    /// `registration_client`) in the `recaptcha` header. On success the server emails a code:
    /// continue with `verify_email`, then `send_phone_code` / `verify_phone` while the status
    /// is `PENDING_PHONE`, then `complete`, then sign in with the password. Errors:
    /// `USER_EXISTS` (409), `INVALID_EMAIL`, `INVALID_PASSWORD`, `INVALID_AGREEMENT`,
    /// `BAD_REQUEST` (invalid phone), `PHONE_NUMBER_NOT_AVAILABLE` (400), `INVALID_RECAPTCHA`
    /// (403), `INVALID_CAPTCHA`.
    ///
    /// `POST /api/v1/registration/initiate`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// Public: works without signing in.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn initiate(&self, params: RegistrationInitiateParams) -> Result<RegistrationState> {
        self.client
            .request(Service::Auth, Method::POST, "/api/v1/registration/initiate")
            .public()
            .header("captcha", &params.captcha)
            .header("recaptcha", &params.recaptcha)
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Start a passwordless registration on behalf of a merchant
    ///
    /// Variant used by the embeddable merchant widget: no password, the client is linked to
    /// `merchantId` / `externalClientId`. Same headers, steps and errors as `initiate`; finish
    /// with `complete_sdk`.
    ///
    /// `POST /api/v1/registration/sdk/initiate`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// Public: works without signing in.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn initiate_sdk(
        &self,
        params: RegistrationInitiateSdkParams,
    ) -> Result<RegistrationState> {
        self.client
            .request(
                Service::Auth,
                Method::POST,
                "/api/v1/registration/sdk/initiate",
            )
            .public()
            .header("captcha", &params.captcha)
            .header("recaptcha", &params.recaptcha)
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Confirm the registration email with the emailed code
    ///
    /// Wrong codes answer `INVALID_CODE`, `INVALID_EMAIL_CODE` or `BAD_REQUEST`. The code
    /// expires after 5 minutes in the web app.
    ///
    /// `POST /api/v1/registration/email/verify`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// Public: works without signing in.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn verify_email(
        &self,
        params: RegistrationVerifyEmailParams,
    ) -> Result<RegistrationState> {
        self.client
            .request(
                Service::Auth,
                Method::POST,
                "/api/v1/registration/email/verify",
            )
            .public()
            .json(params)
            .send()
            .await?
            .json()
            .await
    }

    /// Resend the registration email code
    ///
    /// Allowed once a minute; earlier calls answer `EMAIL_CODE_ERROR`.
    ///
    /// `POST /api/v1/registration/email/resend-code`
    ///
    /// Public: works without signing in.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails.
    pub async fn resend_email_code(&self, params: RegistrationResendEmailCodeParams) -> Result<()> {
        self.client
            .request(
                Service::Auth,
                Method::POST,
                "/api/v1/registration/email/resend-code",
            )
            .public()
            .json(params)
            .send()
            .await?;
        Ok(())
    }

    /// Send the registration SMS code
    ///
    /// Errors `SMS_SENDING_ERROR`, `SMS_CODE_ERROR` (with `subStatus` `TOO_MANY_ATTEMPTS`,
    /// `TOO_SOON` or `UNSUPPORTED_COUNTRY`), `BAD_REQUEST` (invalid phone).
    ///
    /// `POST /api/v1/registration/phone/send-code`
    ///
    /// Public: works without signing in.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails.
    pub async fn send_phone_code(&self, params: RegistrationSendPhoneCodeParams) -> Result<()> {
        self.client
            .request(
                Service::Auth,
                Method::POST,
                "/api/v1/registration/phone/send-code",
            )
            .public()
            .json(params)
            .send()
            .await?;
        Ok(())
    }

    /// Confirm the registration phone with the SMS code
    ///
    /// Wrong codes answer `INVALID_CODE`, `INVALID_SMS_CODE` or `BAD_REQUEST`.
    ///
    /// `POST /api/v1/registration/phone/verify`
    ///
