/// Endpoints of `client.support()`.
#[derive(Debug, Clone, Copy)]
pub struct Support<'a> {
    client: &'a Client,
}

impl Support<'_> {
    /// Send a message to support
    ///
    /// Multipart form: `request` is a JSON-encoded `SupportRequest` sent as a plain text part,
    /// `files` are optional attachments (the web app repeats the `files` part once per file).
    /// The public support form adds a Google reCAPTCHA v3 token in the `recaptcha` header;
    /// errors seen: `INVALID_EMAIL`, `INVALID_RECAPTCHA`.
    ///
    /// `POST /api/v1/support`
    ///
    /// **Experimental:** the endpoint may change without notice.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub async fn send(&self, params: SupportSendParams) -> Result<SupportResponse> {
        self.client
            .request(Service::Kyc, Method::POST, "/api/v1/support")
            .header("recaptcha", &params.recaptcha)
            .multipart(
                Multipart::new()
                    .json("request", &params.request)
                    .files("files", params.files.into_iter().flatten()),
            )
            .send()
            .await?
            .json()
            .await
    }
}

